import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department with optional role filter.
    Supports partial matching for department names.
    """
    department = request.args.get('department', '')
    role_filter = request.args.get('role', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Build base query
    base_query = "SELECT id, username, email, role, department FROM users WHERE department LIKE '%" + department + "%'"

    # Apply role filter if provided
    if role_filter:
        base_query += " AND role = '" + role_filter + "'"

    # Filter active users unless explicitly requested
    if include_inactive.lower() != 'true':
        base_query += " AND active = 1"

    # Log the search action
    try:
        db = get_db()
        db.execute("INSERT INTO audit_log (action) VALUES (?)", 
                   (f"search:dept={department}",))
        db.commit()
    except Exception:
        pass  # Non-critical logging

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    cursor = db.execute("SELECT id, username, email, role, department FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user record."""
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Username required'}), 400

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, role, department) VALUES (?, ?, ?, ?)",
            (data['username'], data.get('email', ''), 
             data.get('role', 'user'), data.get('department', ''))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', False))
